using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionFaintedTargetEnum", menuName = "Data/Battle/Enums/Target/CompanionFainted Target Enum")]
public class CompanionFaintedTargetEnum : TargetEnum
{
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void PopulateTargetInstanceLists()
	{
		List<GameObject> decayedCompanions = currentCompanions.DecayedCompanions;
		List<CompanionInitializer> list = new List<CompanionInitializer>();
		for (int i = 0; i < decayedCompanions.Count; i++)
		{
			CompanionInitializer componentInChildren = decayedCompanions[i].GetComponentInChildren<CompanionInitializer>();
			list.Add(componentInChildren);
		}
		list = list.OrderBy((CompanionInitializer _) => _.PositioningIndex).ToList();
		for (int j = 0; j < list.Count; j++)
		{
			ReferenceSingleton<InputManager>.Instance.horizontalTargetInstanceList.Add(list[j].CompanionFaintedTargetInstance);
		}
	}

	public override void AfterPopulateTargetInstanceLists()
	{
		if (currentCompanions.DecayedCompanions.Count == 1 && currentCompanions.RuntimeCompanions.Count == 2)
		{
			List<TargetInstance> horizontalTargetInstanceList = ReferenceSingleton<InputManager>.Instance.horizontalTargetInstanceList;
			CompanionInitializer componentInChildren = currentCompanions.DecayedCompanions.First().GetComponentInChildren<CompanionInitializer>();
			int positioningIndex = componentInChildren.PositioningIndex;
			int num = horizontalTargetInstanceList.IndexOf(componentInChildren.CompanionFaintedTargetInstance);
			if (positioningIndex != num)
			{
				horizontalTargetInstanceList.MoveElementFromIndexToIndex(num, positioningIndex);
			}
			TargetInstance companionFaintedTargetInstance = currentCompanions.DecayedCompanions.First().GetComponentInChildren<CompanionInitializer>().CompanionFaintedTargetInstance;
			if (horizontalTargetInstanceList.Contains(companionFaintedTargetInstance))
			{
				ReferenceSingleton<InputManager>.Instance.SetHorizontalIndex(horizontalTargetInstanceList.IndexOf(companionFaintedTargetInstance));
			}
		}
	}
}
